-- -----------------------------------
-- Table structure for `panel_activity_tracker`
-- -----------------------------------

DROP TABLE IF EXISTS `panel_activity_tracker`;
CREATE TABLE `panel_activity_tracker` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `atmid` varchar(60) DEFAULT NULL,
  `city` varchar(60) DEFAULT NULL,
  `state` varchar(60) DEFAULT NULL,
  `Address` text,
  `panelid` varchar(60) DEFAULT NULL,
  `dvrip` varchar(60) DEFAULT NULL,
  `panel_make` varchar(60) DEFAULT NULL,
  `Chest_Door` datetime DEFAULT NULL,
  `Hood_Door` datetime DEFAULT NULL,
  `ATM_Vibration` datetime DEFAULT NULL,
  `ATM_Removal` datetime DEFAULT NULL,
  `ATM_Thermal` datetime DEFAULT NULL,
  `Smoke_Sensor` datetime DEFAULT NULL,
  `Panic_Switch` datetime DEFAULT NULL,
  `Bacroom_Door_Open` datetime DEFAULT NULL,
  `Lobby_PIR_Motion` datetime DEFAULT NULL,
  `Glass_Break` datetime DEFAULT NULL,
  `Camera_Removal` datetime DEFAULT NULL,
  `Speaker_Mic_Removal` datetime DEFAULT NULL,
  `AC_Removal` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=1559 DEFAULT CHARSET=latin1;

